"""Python source for the student/section_preferences.html page template."""

TEMPLATE_SOURCE = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Preferred Sections - SectionSync</title>\n\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            font-family: Arial, Helvetica, sans-serif;\n        }\n\n        body {\n            background: #f7f7fb;\n            color: #25233d;\n        }\n\n        /* SIDEBAR */\n        .sidebar {\n            position: fixed;\n            left: 0;\n            top: 0;\n            width: 240px;\n            height: 100vh;\n            background: #25233d;\n            color: white;\n            padding: 25px 15px;\n        }\n\n        .logo {\n            font-size: 24px;\n            font-weight: bold;\n            padding-left: 15px;\n            margin-bottom: 5px;\n        }\n\n        .portal {\n            color: #aaa8bd;\n            font-size: 13px;\n            padding-left: 16px;\n            margin-bottom: 35px;\n        }\n\n        .nav-link {\n            display: flex;\n            align-items: center;\n            gap: 13px;\n            padding: 13px 15px;\n            margin: 6px 0;\n            color: #d6d4df;\n            text-decoration: none;\n            border-radius: 9px;\n            font-size: 14px;\n            transition: 0.2s;\n        }\n\n        .nav-link:hover {\n            background: #34314f;\n        }\n\n        .nav-link.active {\n            background: #d8c5ff;\n            color: #25233d;\n            font-weight: 600;\n        }\n\n        .icon {\n            width: 20px;\n            text-align: center;\n            font-size: 17px;\n        }\n\n        /* SECTION PREFERENCES DROPDOWN */\n        .section-menu {\n            margin: 6px 0;\n        }\n\n        .section-title {\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            padding: 13px 15px;\n            color: #d6d4df;\n            font-size: 14px;\n            border-radius: 9px;\n        }\n\n        .section-title-left {\n            display: flex;\n            align-items: center;\n            gap: 13px;\n        }\n\n        .arrow {\n            font-size: 12px;\n        }\n\n        .submenu {\n            margin-left: 35px;\n            margin-top: 3px;\n        }\n\n        .submenu a {\n            display: block;\n            padding: 10px 12px;\n            margin: 3px 0;\n            color: #aaa8bd;\n            text-decoration: none;\n            font-size: 13px;\n            border-radius: 7px;\n        }\n\n        .submenu a:hover {\n            color: white;\n            background: #34314f;\n        }\n\n        .submenu a.active {\n            color: white;\n            background: #34314f;\n            font-weight: 600;\n        }\n\n        /* MAIN CONTENT */\n        .main {\n            margin-left: 240px;\n            min-height: 100vh;\n        }\n\n        /* HEADER */\n        .header {\n            height: 75px;\n            background: white;\n            border-bottom: 1px solid #e8e7ee;\n            display: flex;\n            align-items: center;\n            justify-content: flex-end;\n            padding: 0 35px;\n        }\n\n        .profile-area {\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n\n        .notification {\n            position: relative;\n            font-size: 21px;\n            margin-right: 12px;\n        }\n\n        .notification-dot {\n            position: absolute;\n            width: 7px;\n            height: 7px;\n            background: #7845e8;\n            border-radius: 50%;\n            top: 1px;\n            right: 0;\n        }\n\n        .avatar {\n            width: 38px;\n            height: 38px;\n            border-radius: 50%;\n            background: #d8c5ff;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: bold;\n            color: #5c35b5;\n        }\n\n        .profile-name {\n            font-size: 14px;\n            font-weight: 600;\n        }\n\n        .profile-id {\n            font-size: 11px;\n            color: #8a8897;\n            margin-top: 2px;\n        }\n\n        /* PAGE */\n        .content {\n            padding: 35px;\n        }\n\n        .page-heading {\n            margin-bottom: 25px;\n        }\n\n        .page-heading h1 {\n            font-size: 27px;\n            margin-bottom: 7px;\n        }\n\n        .page-heading p {\n            color: #777587;\n            font-size: 14px;\n        }\n\n        /* PROGRAM CARD */\n        .program-card {\n            background: white;\n            border: 1px solid #e8e7ee;\n            border-radius: 12px;\n            padding: 22px 25px;\n            margin-bottom: 20px;\n        }\n\n        .program-card h3 {\n            font-size: 16px;\n            margin-bottom: 8px;\n        }\n\n        .program-info {\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n\n        .program-badge {\n            background: #eee7ff;\n            color: #713ce6;\n            padding: 8px 15px;\n            border-radius: 7px;\n            font-size: 13px;\n            font-weight: 600;\n        }\n\n        .program-text {\n            color: #777587;\n            font-size: 13px;\n        }\n\n        /* PREFERENCE CARD */\n        .preference-card {\n            background: white;\n            border: 1px solid #e8e7ee;\n            border-radius: 12px;\n            padding: 28px;\n        }\n\n        .card-heading {\n            margin-bottom: 25px;\n        }\n\n        .card-heading h2 {\n            font-size: 19px;\n            margin-bottom: 6px;\n        }\n\n        .card-heading p {\n            color: #858391;\n            font-size: 13px;\n        }\n\n        /* PREFERENCE ROW */\n        .preference-row {\n            display: flex;\n            align-items: center;\n            gap: 20px;\n            margin-bottom: 18px;\n        }\n\n        .preference-number {\n            width: 42px;\n            height: 42px;\n            border-radius: 50%;\n            background: #eee7ff;\n            color: #713ce6;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: bold;\n            font-size: 14px;\n            flex-shrink: 0;\n        }\n\n        .preference-label {\n            width: 145px;\n            font-size: 14px;\n            font-weight: 600;\n        }\n\n        .select-wrapper {\n            flex: 1;\n        }\n\n        select {\n            width: 100%;\n            padding: 12px 14px;\n            border: 1px solid #dddbe5;\n            border-radius: 8px;\n            background: white;\n            color: #353346;\n            font-size: 14px;\n            outline: none;\n            cursor: pointer;\n        }\n\n        select:focus {\n            border-color: #7845e8;\n        }\n\n        /* NOTE */\n        .note {\n            background: #f7f3ff;\n            border-left: 4px solid #7845e8;\n            padding: 14px 16px;\n            margin-top: 25px;\n            border-radius: 6px;\n            color: #5c5870;\n            font-size: 13px;\n            line-height: 1.5;\n        }\n\n        /* BUTTON */\n        .button-area {\n            display: flex;\n            justify-content: flex-end;\n            margin-top: 25px;\n        }\n\n        .save-btn {\n            border: none;\n            background: #7845e8;\n            color: white;\n            padding: 12px 24px;\n            border-radius: 8px;\n            font-size: 14px;\n            font-weight: 600;\n            cursor: pointer;\n            transition: 0.2s;\n        }\n\n        .save-btn:hover {\n            background: #6335c8;\n        }\n\n        /* SUCCESS MESSAGE */\n        .success-message {\n            display: none;\n            margin-top: 18px;\n            padding: 12px 15px;\n            border-radius: 7px;\n            background: #edf9f0;\n            color: #287a3e;\n            font-size: 13px;\n        }\n\n        /* RESPONSIVE */\n        @media (max-width: 800px) {\n\n            .sidebar {\n                width: 200px;\n            }\n\n            .main {\n                margin-left: 200px;\n            }\n\n            .content {\n                padding: 25px;\n            }\n\n            .preference-row {\n                gap: 12px;\n            }\n\n            .preference-label {\n                width: 120px;\n            }\n        }\n\n        @media (max-width: 650px) {\n\n            .sidebar {\n                position: relative;\n                width: 100%;\n                height: auto;\n            }\n\n            .main {\n                margin-left: 0;\n            }\n\n            .header {\n                padding: 0 20px;\n            }\n\n            .content {\n                padding: 20px;\n            }\n\n            .preference-row {\n                flex-wrap: wrap;\n            }\n\n            .preference-label {\n                width: auto;\n                flex: 1;\n            }\n\n            .select-wrapper {\n                width: 100%;\n                flex-basis: 100%;\n            }\n        }\n    </style>\n</head>\n\n<body>\n\n    <!-- SIDEBAR -->\n    <div class="sidebar">\n\n        <div class="logo">SectionSync</div>\n        <div class="portal">Student Portal</div>\n\n        <a href="/student/dashboard" class="nav-link">\n            <span class="icon">⌂</span>\n            <span>Dashboard</span>\n        </a>\n\n        <a href="/student/profile" class="nav-link">\n            <span class="icon">◉</span>\n            <span>My Profile</span>\n        </a>\n\n        <a href="/student/fee-verification" class="nav-link">\n            <span class="icon">▣</span>\n            <span>Fee Verification</span>\n        </a>\n\n        <!-- SECTION PREFERENCES -->\n        <div class="section-menu">\n\n            <div class="section-title">\n                <div class="section-title-left">\n                    <span class="icon">☷</span>\n                    <span>Section Preferences</span>\n                </div>\n\n                <span class="arrow">⌃</span>\n            </div>\n\n            <div class="submenu">\n\n                <a href="/student/live-basket-filling">\n                    Live Basket Filling\n                </a>\n\n                <a href="/student/section-preferences" class="active">\n                    Preferred Sections\n                </a>\n\n            </div>\n\n        </div>\n\n        <a href="/student/allocation-status" class="nav-link">\n            <span class="icon">✓</span>\n            <span>Allocation Status</span>\n        </a>\n\n        <a href="/logout" class="nav-link">\n            <span class="icon">↪</span>\n            <span>Logout</span>\n        </a>\n\n    </div>\n\n\n    <!-- MAIN -->\n    <div class="main">\n\n        <!-- HEADER -->\n        <div class="header">\n\n            <div class="profile-area">\n\n                <div class="notification">\n                    ♧\n                    <span class="notification-dot"></span>\n                </div>\n\n                <div class="avatar">\n                    P\n                </div>\n\n                <div>\n                    <div class="profile-name">{{ student[\'student_name\'] }}</div>\n                    <div class="profile-id">{{ student[\'enrollment_no\'] }}</div>\n                </div>\n\n            </div>\n\n        </div>\n\n\n        <!-- CONTENT -->\n        <div class="content">\n\n            <div class="page-heading">\n                <h1>Preferred Sections</h1>\n                <p>Select and arrange your preferred sections in the order you want.</p>\n            </div>\n\n\n            <!-- PROGRAM -->\n            <div class="program-card">\n\n                <h3>Your Program</h3>\n\n                <div class="program-info">\n\n                    <span class="program-badge">\n                    {{ student[\'program\'] }}\n                    </span>\n\n                    <span class="program-text">\n                        You can select sections available for your program.\n                    </span>\n\n                </div>\n\n            </div>\n\n\n            <!-- PREFERENCES -->\n            <div class="preference-card">\n\n                <div class="card-heading">\n                    <h2>Section Preferences</h2>\n\n                    <p>\n                        Choose your preferred sections from highest to lowest priority.\n                    </p>\n                </div>\n\n\n                {% if error %}<div class="note" style="background:#fff0f0;color:#a52b2b;">{{ error }}</div>{% endif %}\n                {% if message %}<div class="success-message" style="display:block;">{{ message }}</div>{% endif %}\n\n                <form method="POST" action="{{ url_for(\'section_preferences\') }}" id="preferencesForm">\n                    {% for number in range(1, 5) %}\n                    <div class="preference-row">\n                        <div class="preference-number">{{ number }}</div>\n                        <div class="preference-label">\n                            {% if number == 1 %}1st{% elif number == 2 %}2nd{% elif number == 3 %}3rd{% else %}4th{% endif %} Preference\n                        </div>\n                        <div class="select-wrapper">\n                            <select class="section-select" name="preference_{{ number }}">\n                                <option value="">Select Section</option>\n                                {% for section in section_options %}\n                                <option value="{{ section }}" {% if saved_preferences.get(number) == section %}selected{% endif %}>{{ student[\'program\'] }} - {{ section }}</option>\n                                {% endfor %}\n                            </select>\n                        </div>\n                    </div>\n                    {% endfor %}\n\n\n                <!-- NOTE -->\n                <div class="note">\n                    <strong>Note:</strong>\n                    Select each section only once. Your preferences will be considered\n                    during the automatic section allocation process based on availability,\n                    capacity, and other allocation rules.\n                </div>\n\n\n                <!-- SUCCESS MESSAGE -->\n                <div class="success-message" id="successMessage">\n                    ✓ Your section preferences have been saved successfully.\n                </div>\n\n\n                <!-- BUTTON -->\n                <div class="button-area">\n\n                    <button class="save-btn" type="submit">\n                        Save Preferences\n                    </button>\n\n                </div>\n                </form>\n\n            </div>\n\n        </div>\n\n    </div>\n\n\n    <!-- JAVASCRIPT -->\n    <script>\n\n        const selects = document.querySelectorAll(".section-select");\n\n        // Prevent the same section from being selected twice\n        selects.forEach(select => {\n\n            select.addEventListener("change", function () {\n\n                const selectedValues = [];\n\n                selects.forEach(item => {\n                    if (item.value !== "") {\n                        selectedValues.push(item.value);\n                    }\n                });\n\n                const duplicates =\n                    selectedValues.filter(\n                        (value, index) =>\n                            selectedValues.indexOf(value) !== index\n                    );\n\n                if (duplicates.length > 0) {\n\n                    alert("You have already selected this section. Please choose another section.");\n\n                    this.value = "";\n                }\n\n            });\n\n        });\n\n\n        function savePreferences() {\n\n            let selected = [];\n\n            selects.forEach(select => {\n\n                if (select.value !== "") {\n                    selected.push(select.value);\n                }\n\n            });\n\n            if (selected.length === 0) {\n\n                alert("Please select at least one preferred section.");\n                return;\n\n            }\n\n            const successMessage =\n                document.getElementById("successMessage");\n\n            successMessage.style.display = "block";\n\n            successMessage.scrollIntoView({\n                behavior: "smooth",\n                block: "center"\n            });\n\n        }\n\n    </script>\n\n</body>\n</html>\n'
